args<-commandArgs(trailingOnly=TRUE);Sys.setenv(PHASE1RR_ROOT=normalizePath(args[1]));source(file.path(Sys.getenv('PHASE1RR_ROOT'),'10_code/phase1rr_common.R'));cid<-args[2];cores<-as.integer(args[3]);if(is.na(cores))cores<-3L
st<-readRDS(file.path(O,paste0(cid,'.GENERATOR_STATE.rds')));stopifnot(isTRUE(st$fidelity_pass));universe<-st$observed$gene;seedbase<-20261019+match(cid,c('mTKO_4T1_T25','mTKO_B16_T17','mTKO_MC38_T15'))*100000
# Prospective spike selection uses only guide count and baseline abundance.
set.seed(seedbase+50000);eligible<-copy(st$observed[,c('gene','n_guides','mean_baseline_raw')]);eligible[,ab_stratum:=pmin(3,ceiling(rank(mean_baseline_raw,ties.method='first')/.N*3))];eligible[,guide_stratum:=ifelse(n_guides<=4,'3-4',ifelse(n_guides<=6,'5-6','7+'))];eligible[,stratum:=paste(ab_stratum,guide_stratum)];eligible[,random_order:=runif(.N)];setorder(eligible,stratum,random_order);eligible[,within_stratum_order:=seq_len(.N),by=stratum];setorder(eligible,within_stratum_order,stratum);sp<-eligible[1:600];sp<-sp[sample(.N)];sp[,true_log2FC:=rep(c(.5,1,2),each=200)*rep(c(-1,1),300)];write_tsv(sp,file.path(Q,paste0(cid,'.PRESPECIFIED_SPIKE_GENES.tsv')))
mu_sp<-st$mu0;factors<-2^sp$true_log2FC;names(factors)<-sp$gene;f<-factors[st$gene];f[is.na(f)]<-1;mu_sp[,4:6]<-mu_sp[,4:6]*f;before<-colSums(mu_sp);mu_sp<-sweep(mu_sp,2,before/st$raw_depth,'/');write_tsv(data.table(sample=colnames(mu_sp),compositional_log2_shift=log2(before/st$raw_depth)),file.path(Q,paste0(cid,'.SPIKE_COMPOSITION.tsv')))
run_one<-function(b,stage){
 set.seed(seedbase+switch(stage,TRAIN=0L,HELDOUT=20000L,SPIKE=40000L)+b);cts<-gen_counts(st,if(stage=='SPIKE')mu_sp else st$mu0,copula=st$method!='INDEPENDENT_NB');fit<-fit_dataset(cts,st$keep,st$gene);stopifnot(identical(fit$gene$gene,universe),all(is.finite(fit$gene$PRIMARY_GENE_SCORE)));list(score=fit$gene$PRIMARY_GENE_SCORE,effect=fit$gene$median_log2FC,common_dispersion=fit$common_dispersion,seed=seedbase+switch(stage,TRAIN=0L,HELDOUT=20000L,SPIKE=40000L)+b)
}
run_stage<-function(stage,B){fn<-file.path(O,paste0(cid,'.',stage,'.rds'));if(file.exists(fn)){z<-readRDS(fn);stopifnot(ncol(z$score)==B);return(z)};parts<-list()
 for(start in seq(1,B,by=20)){ind<-start:min(B,start+19);chunkfile<-file.path(O,paste0(cid,'.',stage,'.CHUNK_',start,'.rds'));if(file.exists(chunkfile)){res<-readRDS(chunkfile)}else{res<-parallel::mclapply(ind,function(b)run_one(b,stage),mc.cores=cores,mc.preschedule=FALSE,mc.set.seed=FALSE);stopifnot(all(vapply(res,is.list,TRUE)));saveRDS(res,chunkfile,compress=FALSE)};parts<-c(parts,res)
  if(length(parts)==200 & stage=='TRAIN'){pilot<-list(gene=universe,n_simulations=200,all_finite=TRUE,same_guide_identity=TRUE,same_gene_identity=TRUE,completed_at=as.character(Sys.time()));write_json(pilot,file.path(Q,paste0(cid,'.PILOT_VALIDATION.json')),auto_unbox=TRUE,pretty=TRUE)}
  # quiet file checkpoint, no progress spam
  saveRDS(list(gene=universe,completed=length(parts),stage=stage,last_seed=res[[length(res)]]$seed),file.path(Q,paste0(cid,'.SIMULATION_PROGRESS.rds')))
 }
 z<-list(gene=universe,score=do.call(cbind,lapply(parts,'[[','score')),effect=do.call(cbind,lapply(parts,'[[','effect')),common_dispersion=vapply(parts,'[[',0,'common_dispersion'),seeds=vapply(parts,'[[',0,'seed'));saveRDS(z,fn,compress=FALSE);z
}
cat('START TRAIN',cid,format(Sys.time()),'cores',cores,'\n');flush.console();tr<-run_stage('TRAIN',1000);cat('TRAIN complete',format(Sys.time()),'\n');flush.console();ho<-run_stage('HELDOUT',100);cat('HELDOUT complete',format(Sys.time()),'\n');flush.console();spres<-run_stage('SPIKE',60);cat('SPIKE complete',format(Sys.time()),'\n');flush.console()
emp_p<-function(score)(1+rowSums(abs(tr$score)>=abs(score)))/1001
observed<-copy(st$observed);observed[,empirical_P:=emp_p(PRIMARY_GENE_SCORE)];observed[,empirical_FDR:=p.adjust(empirical_P,'BH')];observed[,empirical_FDR_qualified:=empirical_FDR<=.1];observed[,effect_qualified:=abs(median_log2FC)>=.5];write_tsv(observed,file.path(T,paste0(cid,'.EMPIRICAL_INFERENCE.tsv')))
cal<-list();hists<-numeric(1001);strata<-copy(eligible);strata<-strata[match(universe,gene)]
stratrates<-list()
for(b in 1:100){pp<-emp_p(ho$score[,b]);q<-p.adjust(pp,'BH');hists<-hists+tabulate(round(pp*1001),nbins=1001);cal[[b]]<-data.table(contrast=cid,simulation=b,p05=mean(pp<=.05),p01=mean(pp<=.01),median_P=median(pp),BH_n=sum(q<=.1),seed=ho$seeds[b]);stratrates[[b]]<-rbind(data.table(stratum=paste0('ABUNDANCE_',strata$ab_stratum),P=pp),data.table(stratum=paste0('N_GUIDES_',strata$guide_stratum),P=pp))[,.(n_genes=.N,p05=mean(P<=.05)),by=stratum][,simulation:=b]}
cal<-rbindlist(cal);stcal<-rbindlist(stratrates);cdf<-cumsum(hists)/sum(hists);ks<-max(abs(cdf-seq_len(1001)/1001));med<-which(cdf>=.5)[1]/1001;anybh<-mean(cal$BH_n>0);maxrate<-max(stcal[n_genes>=100,.(p05=mean(p05)),by=stratum]$p05)
calpass<-med>=.47 & med<=.53 & ks<=.03 & mean(cal$p05)>=.035 & mean(cal$p05)<=.065 & mean(cal$p01)>=.005 & mean(cal$p01)<=.017 & anybh<=.15 & maxrate<=.10
write_tsv(cal,file.path(Q,paste0(cid,'.GLOBAL_NULL_CALIBRATION.tsv')));write_tsv(stcal,file.path(Q,paste0(cid,'.NULL_STRATUM_CALIBRATION.tsv')));write_tsv(data.table(P=seq_len(1001)/1001,count=hists,empirical_CDF=cdf),file.path(Q,paste0(cid,'.NULL_P_HISTOGRAM.tsv')))
summary<-data.table(contrast=cid,n_training=1000,n_heldout=100,pooled_median_P=med,discrete_KS=ks,mean_typeI_05=mean(cal$p05),MC_SE_typeI_05=sd(cal$p05)/10,mean_typeI_01=mean(cal$p01),MC_SE_typeI_01=sd(cal$p01)/10,global_null_BH_any_fraction=anybh,max_stratum_typeI_05=maxrate,CALIBRATION_PASS=calpass);write_tsv(summary,file.path(Q,paste0(cid,'.CALIBRATION_SUMMARY.tsv')))
idx<-match(sp$gene,universe);power<-list();fp<-numeric(60)
for(b in 1:60){pp<-emp_p(spres$score[,b]);q<-p.adjust(pp,'BH');selected<-q<=.1;fp[b]<-sum(selected & !universe %in% sp$gene)/max(1,sum(selected));tmp<-copy(sp);tmp[,P:=pp[idx]];tmp[,FDR:=q[idx]];tmp[,estimated_effect:=spres$effect[idx,b]];power[[b]]<-tmp[,.(n_genes=.N,power_P05=mean(P<=.05),power_BH10=mean(FDR<=.10),sign_accuracy=mean(estimated_effect*true_log2FC>0),median_abs_effect_bias=median(abs(estimated_effect-true_log2FC))),by=.(abs_effect=abs(true_log2FC))][,simulation:=b]}
power<-rbindlist(power);ps<-power[,lapply(.SD,mean),by=abs_effect,.SDcols=c('power_P05','power_BH10','sign_accuracy','median_abs_effect_bias')];large<-ps[abs_effect==2];medium<-ps[abs_effect==1];pass<-large$power_P05>=.60 & medium$power_P05>=.30 & large$sign_accuracy>=.90 & large$median_abs_effect_bias<=.50 & mean(fp)<=.15;partial<-large$power_P05>=.30 & large$sign_accuracy>=.80 & mean(fp)<=.15
ps[,contrast:=cid];ps[,SPIKE_STATUS:=if(pass)'PASS' else if(partial)'PARTIAL' else 'FAIL'];ps[,mean_BH_false_discovery_proportion:=mean(fp)];write_tsv(power,file.path(Q,paste0(cid,'.SPIKE_REPLICATES.tsv')));write_tsv(ps,file.path(Q,paste0(cid,'.SPIKE_SUMMARY.tsv')));write_tsv(data.table(simulation=1:60,false_discovery_proportion=fp),file.path(Q,paste0(cid,'.SPIKE_FDR.tsv')))
cat('DONE',cid,'CALIBRATION',calpass,'SPIKE',ps$SPIKE_STATUS[1],format(Sys.time()),'\n')
